      "solution_markdown": `### ক) প্রারম্ভিক মূলধন নির্ণয়:
$$\\text{প্রারম্ভিক মূলধন} = \\text{প্রারম্ভিক মোট সম্পদ} - \\text{প্রারম্ভিক মোট দায়}$$
- প্রারম্ভিক মোট সম্পদ = ২,৫০,০০০ টাকা
- প্রারম্ভিক মোট দায় = ১,০০,০০০ টাকা
- **প্রারম্ভিক মূলধন** = $২,৫০,০০০ - ১,০০,০০০$ = **১,৫০,০০০ টাকা**

---

### খ) সমাপনী মূলধন নির্ণয়:
$$\\text{সমাপনী মূলধন} = \\text{সমাপনী মোট সম্পদ} - \\text{সমাপনী মোট দায়}$$
- সমাপনী মোট সম্পদ = ৩,৬০,০০০ টাকা
- সমাপনী মোট দায় = ৮০,০০০ টাকা
- **সমাপনী মূলধন** = $৩,৬০,০০০ - ৮০,০০০$ = **২,৮০,০০০ টাকা**

---

### গ) লাভ বা ক্ষতি নির্ণয়:
$$\\text{নিট লাভ / ক্ষতি} = (\\text{সমাপনী মূলধন} + \\text{উত্তোলন}) - (\\text{প্রারম্ভিক মূলধন} + \\text{অতিরিক্ত মূলধন})$$
- $(\\text{সমাপনী মূলধন} + \\text{উত্তোলন}) = ২,৮০,০০০ + ৩০,০০০ = ৩,১০,০০০ \\text{ টাকা}$
- $(\\text{প্রারম্ভিক মূলধন} + \\text{অতিরিক্ত মূলধন}) = ১,৫০,০০০ + ২০,০০০ = ১,৭০,০০০ \\text{ টাকা}$
- **নিট লাভ** = $৩,১০,০০০ - ১,৭০,০০০$ = **১,৪০,০০০ টাকা**

> **সিদ্ধান্ত:** ২০২৫ হিসাবকালে জনাব নোমানের ব্যবসায়ে **১,৪০,০০০ টাকা নিট লাভ** অর্জিত হয়েছে।`
