        "খ) মোট মূলধন জাতীয় ব্যয়ের পরিমাণ নির্ধারণ করো।",
        "গ) বিলম্বিত মুনাফা জাতীয় ব্যয়ের পরিমাণ চিহ্নিত করো।"
