      "solution_markdown": `### ক) মূলধন জাতীয় প্রাপ্তি ও মূলধন জাতীয় আয়:
1. **মূলধন জাতীয় প্রাপ্তি (Capital Receipts):**
   - মোটরগাড়ি বিক্রয় বাবদ মোট নগদ প্রাপ্তি = ২,৫০,০০০ টাকা
   - ব্যাংক হতে ঋণ গ্রহণ = ৩,০০,০০০ টাকা
   - **মোট মূলধন জাতীয় প্রাপ্তি** = $২,৫০,০০০ + ৩,০০,০০০$ = **৫,৫০,০০০ টাকা**

2. **মূলধন জাতীয় আয় (Capital Gain):**
   $$\\text{মূলধন জাতীয় আয়} = \\text{স্থায়ী সম্পদ বিক্রয়মূল্য} - \\text{সম্পদের বহিমূল্য}$$
   - মোটরগাড়ি বিক্রয়মূল্য = ২,৫০,০০০ টাকা
   - মোটরগাড়ির বহিমূল্য = ২,২০,০০০ টাকা
   - **মূলধন জাতীয় আয়** = $২,৫০,০০০ - ২,২০,০০০$ = **৩০,০০০ টাকা**

---

### খ) মোট মূলধন জাতীয় ব্যয় (Capital Expenditure):
স্থায়ী সম্পদ ক্রয়ের সাথে সাথে ব্যবহারের উপযোগী করা পর্যন্ত সকল অনুষঙ্গিক খরচ মূলধন জাতীয় ব্যয়ের অন্তর্ভুক্ত হয়:
- ফটোকপি মেশিনের ক্রয়মূল্য = ১,২০,০০০ টাকা
- বহন খরচ = ২,০০০ টাকা
- সংস্থাপন ব্যয় = ৩,০০০ টাকা
- **মোট মূলধন জাতীয় ব্যয়** = $১,২০,০০০ + ২,০০০ + ৩,০০০$ = **১,২৫,০০০ টাকা**

---

### গ) বিলম্বিত মুনাফা জাতীয় ব্যয় (Deferred Revenue Expenditure):
- ব্যবসায়ের নতুন শাখা সম্প্রসারণে প্রাথমিক বিজ্ঞাপন ব্যয় = **৫০,০০০ টাকা** (কারণ এর সুফল একাধিক বছর ধরে ভোগ করা যাবে)।`
