      "solution_markdown": `### ক) মূলধন জাতীয় ব্যয়ের পরিমাণ নির্ণয়:
রেস্টুরেন্টের দীর্ঘমেয়াদী ব্যবহারের জন্য সম্পদ ক্রয় এবং যন্ত্রের আয়ুষ্কাল বৃদ্ধিকারী ব্যয় মূলধন জাতীয় ব্যয়:
- তৈজসপত্র ক্রয় = ৮০,০০০ টাকা
- সাজসজ্জা-সামগ্রী ক্রয় = ২০,০০০ টাকা
- নষ্ট রেফ্রিজারেটরের নতুন কম্প্রেসার ক্রয় = ৮,০০০ টাকা *(কম্প্রেসার প্রতিস্থাপন রেফ্রিজারেটরের কার্যকর আয়ুষ্কাল বাড়াবে)*
- **মোট মূলধন জাতীয় ব্যয়** = $৮০,০০০ + ২০,০০০ + ৮,০০০$ = **১,০৮,০০০ টাকা**

---

### খ) মুনাফা জাতীয় আয়ের পরিমাণ নির্ণয়:
রেস্টুরেন্টের নিয়মিত সেবা ও খাবার পরিবেশন হতে অর্জিত আয়:
- জন্মদিনের অনুষ্ঠান আয়োজন বাবদ প্রাপ্তি = ২২,০০০ টাকা
- গ্রাহকদের সেবা প্রদানের জন্য প্রাপ্তি = ২৫,০০০ টাকা
- **মোট মুনাফা জাতীয় আয়** = $২২,০০০ + ২৫,০০০$ = **৪৭,০০০ টাকা**

---

### গ) মুনাফা জাতীয় ব্যয়ের পরিমাণ নির্ণয়:
রেস্টুরেন্টের দৈনন্দিন পরিচালন খরচ:
- প্রচার ও বিজ্ঞাপন বাবদ ব্যয় = ৩,০০০ টাকা
- ভ্যানগাড়ি নিয়মিত মেরামত = ১,০০০ টাকা
- কর্মচারীদের বেতন প্রদান = ৯,০০০ টাকা
- **মোট মুনাফা জাতীয় ব্যয়** = $৩,০০০ + ১,০০০ + ৯,০০০$ = **১৩,০০০ টাকা**`
