      "stem": "মেসার্স দিগন্ত ট্রেডার্স ২০২৫ সালের জন্য নিম্নোক্ত তথ্য প্রদান করে:\n\n১. চলতি ২০২৫ সালে মোট বাড়িভাড়া নগদ পাওয়া গেল ৭০,০০০ টাকা। এর মধ্যে ১০,০০০ টাকা ২০২৪ সালের বকেয়া এবং ১৫,০০০ টাকা ২০২৬ সালের অগ্রিম সংক্রান্ত।\n২. কর্মচারীদের বেতন প্রদান করা হলো ৫৫,০০০ টাকা। যার মধ্যে ৫,০০০ টাকা বিগত বছরের এবং চলতি বছরের বকেয়া বেতন রয়েছে ৮,০০০ টাকা।\n৩. জমি ক্রয়ের দলিল রেজিস্ট্রি ও স্ট্যাম্প খরচ ২৫,০০০ টাকা।\n৪. পণ্য ক্রয়ের জাহাজ ভাড়া ও খালাস খরচ ৬,০০০ টাকা।",
