      "solution_markdown": `### ক) বাড়িভাড়া খাতের মুনাফা জাতীয় প্রাপ্তি বনাম মুনাফা জাতীয় আয়:
1. **মুনাফা জাতীয় প্রাপ্তি:** চলতি বছর মোট নগদ প্রাপ্তি = **৭০,০০০ টাকা**
2. **প্রকৃত মুনাফা জাতীয় আয় নির্ণয়:**
   $$\\text{চলতি আয়} = \\text{মোট প্রাপ্তি} - \\text{বিগত বছরের বকেয়া} - \\text{পরবর্তী বছরের অগ্রিম}$$
   - মোট প্রাপ্তি = ৭০,০০০ টাকা
   - বাদ: বিগত ২০২৪ সালের বকেয়া প্রাপ্তি = (১০,০০০) টাকা
   - বাদ: পরবর্তী ২০২৬ সালের অগ্রিম প্রাপ্তি = (১৫,০০০) টাকা
   - **২০২৫ সালের প্রকৃত মুনাফা জাতীয় আয়** = $৭০,০০০ - ১০,০০০ - ১৫,০০০$ = **৪৫,০০০ টাকা**

---

### খ) প্রকৃত মুনাফা জাতীয় বেতন ব্যয়:
$$\\text{প্রকৃত ব্যয়} = \\text{মোট পরিশোধ} - \\text{বিগত বছরের বকেয়া পরিশোধ} + \\text{চলতি বছরের বকেয়া}$$
- মোট বেতন প্রদান = ৫৫,০০০ টাকা
- বাদ: বিগত বছরের বকেয়া = (৫,০০০) টাকা
- যোগ: চলতি বছরের বকেয়া বেতন = +৮,০০০ টাকা
- **২০২৫ সালের মুনাফা জাতীয় বেতন ব্যয়** = $৫০,০০০ + ৮,০০০$ = **৫৮,০০০ টাকা**

---

### গ) মূলধন বনাম মুনাফা জাতীয় ব্যয়ের বিভাজন:
- **মূলধন জাতীয় ব্যয়:** জমি ক্রয়ের দলিল রেজিস্ট্রি ও স্ট্যাম্প খরচ = **২৫,০০০ টাকা** *(স্থায়ী সম্পদ অর্জনের অপরিহার্য প্রত্যক্ষ ব্যয়)*।
- **মুনাফা জাতীয় ব্যয়:** পণ্য ক্রয়ের জাহাজ ভাড়া ও খালাস খরচ = **৬,০০০ টাকা** *(পণ্য আমদানির নিয়মিত প্রত্যক্ষ পরিচালন ব্যয়)*।`
